* {
  box-sizing: border-box;
}
body {
  margin: 0;
  font-family: system-ui, sans-serif;
  color: #31594c;
  background: #e5eee0;
}
main {
  height: 100dvh;
  overflow: hidden;
  background: radial-gradient(ellipse at 45% 25%, #fff8e4, #d0e8df);
}
.canvas {
  position: absolute;
  inset: 0;
}
header {
  position: absolute;
  left: 25px;
  right: 25px;
  top: 22px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 15px;
  font-size: 13px;
}
a {
  color: inherit;
  text-decoration: none;
  font-size: 23px;
  font-weight: 700;
}
button {
  cursor: pointer;
  border: 1px solid #ffffff80;
  background: #faffeecc;
  color: #31594c;
  border-radius: 12px;
  padding: 12px 18px;
}
header span {
  margin-right: auto;
}
.score {
  position: absolute;
  top: 82px;
  right: 25px;
  background: #ffffeccc;
  border-radius: 14px;
  padding: 15px;
}
footer {
  position: absolute;
  bottom: 24px;
  left: 0;
  right: 0;
  text-align: center;
  font-size: 11px;
  color: #6e8d7b;
  pointer-events: none;
}
.win,
.message {
  position: absolute;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
  background: #fffff0ed;
  border-radius: 20px;
  padding: 30px;
  text-align: center;
  min-width: 300px;
}
.win h1 {
  font-size: 29px;
  font-weight: 500;
  letter-spacing: -1px;
}
.win p {
  font-size: 12px;
}
.controls {
  display: none;
}
.webgl-fallback {
  position: absolute;
  top: 40%;
  left: 10%;
  right: 10%;
  text-align: center;
}
@media (max-width: 700px) {
  header {
    left: 15px;
    right: 15px;
  }
  header span {
    font-size: 10px;
  }
  .controls {
    display: flex;
    position: absolute;
    bottom: 30px;
    left: 20px;
    right: 20px;
    gap: 6px;
  }
  .controls button {
    width: 45px;
    height: 45px;
    padding: 0;
    touch-action: none;
    font-size: 20px;
  }
  .controls button:last-child {
    margin-left: auto;
  }
  footer {
    bottom: 90px;
    font-size: 9px;
  }
}

