  phase: "landing",
  playing: false,
  building: false,
  history: [],
  future: [],
  score: [],
  won: false,
  notice: "",
  error: "",
  saved: false,
  drafts: [],
  draftHistory: {},
  readOnly: false,
  reset: 0,
  set: setState,
  async save() {
