          command.geometry.detail === "refined") ||
        command.type === "set_material" ||
        command.type === "set_transform" ||
        command.type === "set_behavior" ||
        command.type === "set_environment" ||
        command.type === "remove_entity" ||
        command.type === "commit_revision";
