          prompt,
          project,
          selected,
        });
        const response = await fetch(request.url, { ...request.init, signal });
        if (!response.ok) {
          const body = await response.json();
          if (active === controller && !signal.aborted)
            setState({
              generationErrorCode:
                typeof body.code === "string" ? body.code : undefined,
            });
